  </section>
 </div>
</template>
<script>
import BagItemIcon from './BagItemIcon.vue';
export default{components:{BagItemIcon},props:{panel:Object,busy:Boolean,error:String,notice:String,teamSize:Number,money:{type:Number,default:0}},data:()=>({previousFocus:null}),computed:{rescue(){return this.panel.mode==='rescue';},invitation(){return this.panel.mode==='invitation';}},mounted(){this.previousFocus=document.activeElement;this.$nextTick(()=>this.$el.querySelector('button')?.focus({preventScroll:true}));},beforeDestroy(){this.previousFocus?.isConnected && this.previousFocus.focus({preventScroll:true});},methods:{trapFocus(e){const nodes=[...this.$el.querySelectorAll('button:not(:disabled)')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}};
</script>
